head.b:skin:
/* ---------------------------------------------------------------------------------------
[STEPS 1-10] TITAN CORE DESIGN SYSTEM - RESPONSIVE TYPOGRAPHY FIX v26.0
--------------------------------------------------------------------------------------- */
:root {
    --primary: #ce1212; --primary-dark: #a00d0d;
    --secondary: #37373f; --accent: #ffc107;
    --bg-body: #f8f9fa; --bg-card: #ffffff;
    --text-main: #1d1d1f; --text-muted: #86868b;
    --font-main: "Inter", sans-serif; --font-accent: "Amatic SC", sans-serif;
    --font-mono: "JetBrains Mono", monospace;
    --transition: 0.4s cubic-bezier(0.165, 0.84, 0.44, 1);
    --z-navbar: 1030; --z-mobile-nav: 1050; --z-toast: 1100;
    --shadow-sm: 0 4px 12px rgba(0,0,0,0.03);
    --shadow-lg: 0 20px 60px rgba(0,0,0,0.08);
    --radius-xl: 24px;
}

[data-theme='dark'] { 
    --bg-body: #0a0a0c; --bg-card: #1c1c1e; 
    --text-main: #f5f5f7; --text-muted: #a1a1a6; 
}

/* [FLUID TYPOGRAPHY LOGIC] */
h1, .display-1 { font-size: clamp(2.5rem, 8vw, 5rem); line-height: 1.1; }
h2, .display-2 { font-size: clamp(2rem, 6vw, 4rem); }
h3, .display-3 { font-size: clamp(1.75rem, 5vw, 3rem); }
.lead { font-size: clamp(1rem, 2.5vw, 1.25rem); }

/* [STEP 94] CLEAN AUDIT & GLOBAL PERFORMANCE */
body { font-family: var(--font-main); background: var(--bg-body); color: var(--text-main); padding-top: 85px; padding-bottom: 95px; transition: background 0.3s; overflow-x: hidden; -webkit-font-smoothing: antialiased; }
body.rtl { direction: rtl; text-align: right; }

/* [STEP 75] GLOBAL SCROLL FILL */
#scroll-fill { position: fixed; top: 0; left: 0; height: 4px; background: var(--primary); z-index: 2100; width: 0%; transition: 0.1s; box-shadow: 0 0 15px var(--primary); }

/* [STEP 77] NON-FIXED BREADCRUMBS */
.breadcrumb-flat { font-size: 0.65rem; font-weight: 800; text-transform: uppercase; color: var(--text-muted); margin-bottom: 25px; letter-spacing: 1px; display: flex; align-items: center; flex-wrap: wrap; }
.breadcrumb-flat a { color: var(--primary); text-decoration: none; }
.breadcrumb-flat span { margin: 0 8px; opacity: 0.3; }

/* [STEP 86/97] PRODUCT GRID ARCHITECTURE */
.product-card { border: none; border-radius: var(--radius-xl); background: var(--bg-card); box-shadow: var(--shadow-sm); position: relative !important; display: flex; flex-direction: column; height: 100%; overflow: hidden; transition: var(--transition); border: 1px solid rgba(0,0,0,0.02); }
.product-card:hover { transform: translateY(-12px); box-shadow: var(--shadow-lg); }
.product-img-wrapper { position: relative; width: 100%; height: 260px; overflow: hidden; background: #eee; }
.product-img { width: 100%; height: 100%; object-fit: cover; cursor: pointer; transition: 0.8s ease; }

@media (max-width: 576px) { 
    .product-img-wrapper { height: 160px; } 
    .product-card h4 { font-size: 1rem !important; }
    .p-5 { padding: 1.5rem !important; }
}

.wish-btn { position: absolute !important; top: 12px; right: 12px; z-index: 45; background: rgba(255,255,255,0.95); border: none; border-radius: 50%; width: 38px; height: 38px; display: flex; align-items: center; justify-content: center; color: #888; box-shadow: 0 4px 15px rgba(0,0,0,0.1); transition: 0.3s; cursor: pointer; }
.wish-btn.active { color: var(--primary); transform: scale(1.1); background: #fff; }
.compare-toggle { position: absolute; top: 12px; left: 12px; z-index: 45; background: rgba(255,255,255,0.95); border: none; border-radius: 12px; padding: 5px 10px; font-size: 0.6rem; font-weight: 800; text-transform: uppercase; color: #333; cursor: pointer; }

/* [STEP 31] GRID/LIST INTERFACE */
.grid-view .col-lg-4 { width: 33.333%; }
.list-view .col-lg-4 { width: 100%; }
.list-view .product-card { flex-direction: row; height: auto; min-height: 180px; }
.list-view .product-img-wrapper { width: 40%; height: auto; min-height: 180px; }

/* [STEP 93] SHIMMER LOADERS */
.skeleton { background: linear-gradient(90deg, transparent, rgba(0,0,0,0.04), transparent); background-size: 200% 100%; animation: shimmer 1.5s infinite; }
@keyframes shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }

/* [STEP 92/69] COMMERCIAL BADGES */
.badge-ui { position: absolute; bottom: 12px; left: 12px; z-index: 45; padding: 5px 12px; border-radius: 8px; font-size: 0.55rem; font-weight: 900; color: #fff; text-transform: uppercase; letter-spacing: 1px; }
.badge-hot { background: linear-gradient(45deg, #ff416c, #ff4b2b); }

/* [STEP 54/55] VARIATION SWATCHES ENGINE */
.swatch-group { display: flex; gap: 10px; margin: 15px 0; }
.swatch-item { width: 32px; height: 32px; border-radius: 50%; border: 3px solid transparent; cursor: pointer; transition: 0.25s; box-shadow: 0 4px 10px rgba(0,0,0,0.1); position: relative; }
.swatch-item.active { border-color: var(--primary); transform: scale(1.15); }

/* [FIX] CART INTERFACE (RESPONSIVE) */
.cart-item-row { border-bottom: 1px solid rgba(0,0,0,0.05); padding: 15px 0; display: flex; justify-content: space-between; align-items: center; gap: 10px; }
.qty-box { display: flex; align-items: center; gap: 8px; background: rgba(0,0,0,0.03); padding: 6px 14px; border-radius: 50px; }
.qty-btn { cursor: pointer; font-weight: 800; color: var(--primary); font-size: 1.2rem; user-select: none; }
@media (max-width: 576px) { .cart-item-row { flex-direction: column; align-items: flex-start; } .qty-box { margin-top: 10px; width: 100%; justify-content: space-between; } }

/* [STEP 88] LOYALTY MODULE */
.loyalty-widget { background: linear-gradient(135deg, #1d1d1f, #3a3a3c); color: #fff; padding: 25px; border-radius: 20px; margin-bottom: 25px; position: relative; overflow: hidden; border: 1px solid rgba(255,255,255,0.1); }

/* [STEP 72/30] PROOF & TOASTS */
.proof-popup { position: fixed; bottom: 100px; left: 15px; right: 15px; z-index: 1000; background: var(--bg-card); border-radius: 15px; padding: 12px; box-shadow: 0 10px 30px rgba(0,0,0,0.1); display: flex; align-items: center; gap: 12px; max-width: 320px; transform: translateX(-150%); transition: 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275); }
.proof-popup.active { transform: translateX(0); }
@media (min-width: 576px) { .proof-popup { right: auto; } }

/* [STEP 95] WHATSAPP FAB */
.fab-support { position: fixed; right: 20px; bottom: 105px; z-index: 1040; background: #25d366; width: 60px; height: 60px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 2rem; box-shadow: 0 12px 35px rgba(37,211,102,0.4); text-decoration: none; }
@media (min-width: 992px) { .fab-support { bottom: 40px; width: 70px; height: 70px; } }

/* [STEP 89] MAINTENANCE OVERLAY */
#maint-overlay { position: fixed; inset: 0; background: #fff; z-index: 9999; display: none; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 20px; }

.module-section { display: none; padding: 30px 0; min-height: 90vh; width: 100%; }
.module-section.active { display: block !important; }

.form-control, .form-select { border-radius: 15px; padding: 15px; border: 2px solid rgba(0,0,0,0.05); background: var(--bg-body); color: var(--text-main); font-weight: 600; font-size: 0.9rem; }

/* ENTERPRISE NAVIGATION */
.header { background: rgba(255,255,255,0.85); backdrop-filter: blur(20px); height: 80px; z-index: var(--z-navbar); border-bottom: 1px solid rgba(0,0,0,0.05); }
.mobile-toolbar { position: fixed; bottom: 0; left: 0; width: 100%; height: 75px; background: var(--bg-card); display: flex; justify-content: space-around; align-items: center; z-index: var(--z-mobile-nav); border-top: 1px solid rgba(0,0,0,0.1); padding-bottom: env(safe-area-inset-bottom); }
.mobile-toolbar a, .mobile-toolbar button { color: var(--text-main); font-size: 1.5rem; background:none; border:none; transition: 0.2s; }

body.script:
//
/**
 * elgourari ENTERPRISE MONOLITH v26.0 (Unified 100-Step Logic)
 * Resolved: Typography scaling, NaN price errors, SKU crashes, Variant clicks
 */
const App = (function() {
    "use strict";

    let state = {
        catalog: [],
        cart: JSON.parse(localStorage.getItem('sushi_cart')) || [],
        wishlist: JSON.parse(localStorage.getItem('sushi_wishlist')) || [],
        compare: [],
        view: 'grid',
        promo: 0,
        tip: 0,
        currency: localStorage.getItem('sushi_currency') || 'DH',
        rates: { 'DH': 1, 'USD': 0.10, 'EUR': 0.09 },
        settings: { maintenance: false, vat: 0.20, pointsRatio: 0.15 },
        selectedVariant: { color: 'Nori Black', size: 'Standard' }
    };

    const BLOG_URL = 'https://eventsushi.blogspot.com';

    function init() {
        createManifest();
        normalizeCommerceState(); 
        checkAbandonedSession(); 
        fetchCatalogData(); 
        setupRouterEvents();
        setupPickers(); 
        updateGlobalCounters();
        initializeProofEngine(); 
        AOS.init({ duration: 800, once: true });
    }

    // [FIX] Schema Normalizer to force Numbers and prevent NaN calculations
    function normalizeCommerceState() {
        state.cart = state.cart.map(item => {
            return {
                ...item,
                qty: Number(item.qty) || 1,
                price: Number(item.price) || 0
            };
        });
        localStorage.setItem('sushi_cart', JSON.stringify(state.cart));
    }

    // [STEP 97] Fixed start_url for Blob manifests
    function createManifest() {
        const m = { name: "SushiMaster", start_url: window.location.href, display: "standalone" };
        const b = new Blob([JSON.stringify(m)], { type: 'application/json' });
        const l = document.createElement('link'); l.rel = 'manifest'; l.href = URL.createObjectURL(b);
        document.head.appendChild(l);
    }

    function fetchCatalogData() {
        const tag = document.createElement('script');
        tag.src = `${BLOG_URL}/feeds/posts/default?alt=json-in-script&callback=App.parseCatalog&max-results=100`;
        document.body.appendChild(tag);
    }

    function setupRouterEvents() {
        const handle = () => {
            const hash = (window.location.hash || '#home').substring(1);
            document.querySelectorAll('.module-section').forEach(m => m.classList.remove('active'));
            const target = document.getElementById(hash + '-module');
            if (target) {
                target.classList.add('active');
                if(hash === 'cart') renderCartView();
                if(hash === 'wishlist') renderWishlistView();
            }
            window.scrollTo({ top: 0, behavior: 'smooth' });
        };
        window.addEventListener('hashchange', handle); handle();
    }

    function setupPickers() {
        flatpickr("#delivery-time", { enableTime: true, dateFormat: "Y-m-d H:i", minDate: "today" });
    }

    function renderGridView(items, rootId = 'product-grid-root') {
        const root = document.getElementById(rootId);
        if (!root) return;

        if(items.length === 0 && state.catalog.length === 0) {
            root.innerHTML = Array(6).fill(`<div class="col-lg-4 col-6 mb-3"><div class="skeleton sk-img"></div><div class="skeleton sk-text"></div></div>`).join('');
            return;
        }

        root.className = `row gy-4 ${state.view}-view`;
        root.innerHTML = items.map(item => {
            const globalIdx = state.catalog.indexOf(item);
            const isFav = state.wishlist.some(w => w.title === item.title);
            const isHot = item.tags && item.tags.includes('label-Hot');

            return `
            <div class="col-lg-4 col-6 mb-1" data-aos="fade-up">
                <div class="product-card">
                    <button class="compare-toggle" onclick="App.addToCompare(${globalIdx})">Analyze</button>
                    <button class="wish-btn ${isFav ? 'active' : ''}" onclick="App.toggleWishlist(${globalIdx})"><i class="bi bi-heart-fill"></i></button>
                    <div class="product-img-wrapper" onclick="App.openQuickView(${globalIdx})">
                        <img src="${item.img}" class="product-img" loading="lazy">
                        ${isHot ? '<div class="badge-ui badge-hot">Popular</div>' : ''}
                    </div>
                    <div class="p-4 text-center">
                        <h4 class="fw-bold text-truncate m-0 mb-2" style="font-size:1.1rem">${item.title}</h4>
                        <span class="text-danger fw-bold fs-5">${formatPriceString(item.price)}</span>
                        ${rootId === 'wishlist-grid-root' ? `<button class="btn btn-sm btn-danger w-100 rounded-pill mt-3 fw-bold" onclick="App.addToCart(${globalIdx})">Order Now</button>` : ''}
                    </div>
                </div>
            </div>`;
        }).join('') || '<div class="py-5 text-center col-12 text-muted fs-4">No sushi found.</div>';
    }

    function renderCartView() {
        const root = document.getElementById('cart-items-list');
        if (!root) return;
        const subtotal = state.cart.reduce((a, b) => a + (Number(b.price) * Number(b.qty)), 0);
        const total = calculateCommerceFinalTotal(subtotal);

        root.innerHTML = state.cart.map((item, idx) => `
            <div class="cart-item-row" data-aos="fade-left">
                <div class="d-flex align-items-center gap-3">
                    <img src="${item.img}" class="rounded-4" style="width:60px; height:60px; object-fit:cover">
                    <div>
                        <b class="fs-6 d-block">${item.title}</b>
                        <small class="text-muted fw-bold">${formatPriceString(item.price)} / Unit</small>
                    </div>
                </div>
                <div class="d-flex align-items-center gap-3">
                    <div class="qty-box">
                        <span class="qty-btn" onclick="App.updateQuantity(${idx}, -1)">-</span>
                        <span class="fw-bold">${item.qty}</span>
                        <span class="qty-btn" onclick="App.updateQuantity(${idx}, 1)">+</span>
                    </div>
                    <button class="btn-trash" onclick="App.removeFromCart(${idx})"><i class="bi bi-trash3-fill"></i></button>
                </div>
            </div>
        `).join('') || `<div class="py-5 text-center"><i class="bi bi-cart-x display-1 text-muted d-block mb-3"></i><p class="fs-4 text-muted fw-light">Bag is empty.</p></div>`;

        if(document.getElementById('cart-sub-raw')) document.getElementById('cart-sub-raw').innerText = formatPriceString(subtotal);
        if(document.getElementById('tax-display')) document.getElementById('tax-display').innerText = formatPriceString(subtotal * state.settings.vat);
        if(document.getElementById('cart-total-display')) document.getElementById('cart-total-display').innerText = formatPriceString(total);

        const pVal = document.getElementById('points-val');
        if(pVal) pVal.innerText = Math.floor(total * state.settings.pointsRatio);
    }

    function renderWishlistView() { renderGridView(state.wishlist, 'wishlist-grid-root'); }

    function calculateCommerceFinalTotal(sub) {
        let total = Number(sub) + (Number(sub) * state.settings.vat) + state.tip;
        const units = state.cart.reduce((a, b) => a + Number(b.qty), 0);
        if (units >= 10) total *= 0.8; 
        if (document.getElementById('order-type')?.value === 'pickup') total *= 0.9;
        if (state.promo > 0) {
            total -= (total * state.promo);
            document.getElementById('promo-row')?.classList.remove('d-none');
        } else {
            document.getElementById('promo-row')?.classList.add('d-none');
        }
        return total;
    }

    return {
        parseCatalog: function(data) {
            state.catalog = (data.feed.entry || []).map(p => ({
                title: p.title.$t,
                img: p.media$thumbnail.url.replace(/\/s[0-9]+(-c)?\//, '/w800-h600-c/'),
                price: parseFloat(p.category?.find(c => c.term.startsWith('price-'))?.term.split('-')[1] || "0"),
                tags: p.category ? p.category.map(c => c.term) : [],
                sku: p.category?.find(c => c.term.startsWith('sku-'))?.term.split('-')[1] || 'SKU-000',
                qty: 1
            }));
            renderGridView(state.catalog);
        },

        handleSearch: function() {
            const q = document.getElementById('adv-search').value.toLowerCase();
            const matches = state.catalog.filter(i => 
                i.title.toLowerCase().includes(q) || i.sku.toString().toLowerCase().includes(q)
            );
            renderGridView(matches);
        },

        setView: function(type) {
            state.view = type;
            ['btn-grid', 'btn-list'].forEach(id => document.getElementById(id).classList.remove('active'));
            document.getElementById(`btn-${type}`).classList.add('active');
            renderGridView(state.catalog);
        },

        openQuickView: function(globalIndex) {
            const p = state.catalog[globalIndex];
            if (!p) return; 
            document.getElementById('quickview-content').innerHTML = `
                <div class="row g-0"><div class="col-md-6"><img src="${p.img}" class="img-fluid h-100" style="object-fit:cover"></div>
                <div class="col-md-6 p-4 p-md-5">
                    <div class="breadcrumb-flat x-small mb-3">REF: ${p.sku}</div>
                    <h1 class="fw-bold mb-2 fs-3">${p.title}</h1>
                    <div class="text-danger fs-1 fw-bold mb-4">${formatPriceString(p.price)}</div>

                    <div class="swatch-group">
                        <div class="swatch-item bg-dark active" onclick="App.setVariant(this, 'Traditional')"></div>
                        <div class="swatch-item bg-danger" onclick="App.setVariant(this, 'Spicy')"></div>
                    </div>

                    <button class="btn btn-danger w-100 py-4 rounded-pill fw-bold shadow-lg mt-4" onclick="App.addToCart(${globalIndex})">Add Selection</button>

                    <div class='mt-5 pt-3 border-top'><input class='form-control mb-3' placeholder='Review...'><button class='btn btn-sm btn-dark rounded-pill px-4'>Post</button></div>
                </div></div>`;
            new bootstrap.Modal(document.getElementById('quickViewModal')).show();
        },

        setVariant: function(el, name) {
            el.parentElement.querySelectorAll('.swatch-item').forEach(s => s.classList.remove('active'));
            el.classList.add('active');
            state.selectedVariant.color = name;
            App.showToast(`Variant: ${name}`);
        },

        addToCart: function(globalIdx) {
            const p = state.catalog[globalIdx];
            if (!p) return; 
            const exist = state.cart.find(c => c.title === p.title);
            if (exist) exist.qty += 1;
            else state.cart.push({ ...p, qty: 1, variant: state.selectedVariant.color });
            syncMonolith();
            App.showToast(`${p.title} added.`);
            bootstrap.Modal.getInstance(document.getElementById('quickViewModal'))?.hide();
        },

        updateQuantity: function(idx, delta) {
            const item = state.cart[idx];
            if (!item) return;
            item.qty += delta;
            if (item.qty <= 0) state.cart.splice(idx, 1);
            syncMonolith();
            renderCartView();
        },

        removeFromCart: function(idx) { 
            state.cart.splice(idx, 1); syncMonolith(); renderCartView(); 
        },

        toggleWishlist: function(idx) {
            const p = state.catalog[idx];
            const i = state.wishlist.findIndex(w => w.title === p.title);
            if (i > -1) state.wishlist.splice(i, 1);
            else state.wishlist.push(p);
            localStorage.setItem('sushi_wishlist', JSON.stringify(state.wishlist));
            updateGlobalCounters(); renderGridView(state.catalog);
        },

        addToCompare: function(idx) {
            if (state.compare.length >= 2) state.compare.shift();
            state.compare.push(state.catalog[idx]);
            if (state.compare.length === 2) {
                const matrix = document.getElementById('compare-body');
                const c = state.compare;
                matrix.innerHTML = `
                    <tr><th>Box</th><td><img src="${c[0].img}" width="120" class="rounded-4"></td><td><img src="${c[1].img}" width="120" class="rounded-4"></td></tr>
                    <tr><th>Name</th><td class="fw-bold">${c[0].title}</td><td class="fw-bold">${c[1].title}</td></tr>
                    <tr><th>Price</th><td class="text-danger fw-bold">${formatPriceString(c[0].price)}</td><td class="text-danger fw-bold">${formatPriceString(c[1].price)}</td></tr>
                    <tr><th>Action</th>
                        <td><button class="btn btn-danger btn-sm rounded-pill" onclick="App.addToCartByName('${c[0].title}')">Add Left</button></td>
                        <td><button class="btn btn-danger btn-sm rounded-pill" onclick="App.addToCartByName('${c[1].title}')">Add Right</button></td>
                    </tr>`;
                new bootstrap.Modal(document.getElementById('compareModal')).show();
            } else { App.showToast('Select one more item.'); }
        },

        addToCartByName: function(name) {
            const p = state.catalog.find(i => i.title === name);
            if (p) this.addToCart(state.catalog.indexOf(p));
        },

        applyPromo: () => {
            if (document.getElementById('promo-code').value.toUpperCase() === 'SUSHI10') {
                state.promo = 0.10;
                App.showToast('10% Off Applied!');
                renderCartView();
            }
        },

        setTip: function(el, val) {
            state.tip = val;
            document.querySelectorAll('.tip-pill').forEach(b => b.classList.remove('active'));
            el.classList.add('active'); renderCartView();
        },

        setCustomTip: (val) => { state.tip = parseFloat(val) || 0; renderCartView(); },

        toggleTheme: () => {
            const cur = document.body.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
            document.body.setAttribute('data-theme', cur);
            localStorage.setItem('sushi_theme', cur);
            document.getElementById('theme-icon').className = cur === 'dark' ? 'bi bi-sun-fill' : 'bi bi-moon-stars-fill';
            document.getElementById('theme-icon-mob').className = cur === 'dark' ? 'bi bi-sun-fill' : 'bi bi-moon-stars-fill';
        },

        changeCurrency: (c) => {
            state.currency = c; localStorage.setItem('sushi_currency', c);
            renderGridView(state.catalog); if(window.location.hash === '#cart') renderCartView();
        },

        handleConditionalForm: () => {
            document.getElementById('addr-container').style.display = (document.getElementById('order-type').value === 'pickup') ? 'none' : 'block';
            renderCartView(); 
        },

        toggleAdminDashboard: () => { window.location.hash = '#admin'; },

        finalizeOrder: function() {
            const name = document.getElementById('cust-name').value;
            if(!name) { alert('Name required.'); return; }
            const msg = `*ORDER FROM ${name}*%0AItems: ${state.cart.length}%0ATotal: ${document.getElementById('cart-total-display').innerText}`;
            window.open(`https://wa.me/212666000000?text=${msg}`, '_blank');
        },

        generatePDF: () => window.print(),
        exportJSON: () => { const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([JSON.stringify(state.cart)])); a.download='sushi.json'; a.click(); },
        importJSON: (e) => { const r = new FileReader(); r.onload = (v) => { state.cart = JSON.parse(v.target.result); syncMonolith(); location.reload(); }; r.readAsText(e.target.files[0]); },
        showToast: (t) => { document.getElementById('toast-msg').innerText = t; new bootstrap.Toast(document.getElementById('ui-toast')).show(); },
        triggerSupport: () => window.open('https://wa.me/212666000000', '_blank'),

        triggerVoiceSearch: () => {
            if ('webkitSpeechRecognition' in window) {
                const r = new webkitSpeechRecognition();
                r.onresult = (e) => { document.getElementById('adv-search').value = e.results[0][0].transcript; App.handleSearch(); };
                r.start();
            }
        },

        init: init
    };

    function syncMonolith() {
        localStorage.setItem('sushi_cart', JSON.stringify(state.cart));
        updateGlobalCounters();
    }

    function updateGlobalCounters() {
        const u = state.cart.reduce((a, b) => a + Number(b.qty), 0);
        ['cart-count'].forEach(id => { if(document.getElementById(id)) document.getElementById(id).innerText = u; });
        ['wish-count', 'wish-count-mob'].forEach(id => { if(document.getElementById(id)) document.getElementById(id).innerText = state.wishlist.length; });
    }

    function formatPriceString(v) {
        const c = Number(v) * state.rates[state.currency];
        return isNaN(c) ? "0.00 " + state.currency : `${c.toFixed(2)} ${state.currency}`;
    }

    function checkAbandonedSession() {
        if (state.cart.length > 0) document.getElementById('abandoned-alert')?.classList.remove('d-none');
    }

    function initializeProofEngine() {
        const n = ['Mohamed', 'Sarah', 'Amine', 'Laila'];
        setInterval(() => {
            if(state.catalog.length > 0) {
                const u = n[Math.floor(Math.random()*n.length)];
                const p = state.catalog[Math.floor(Math.random()*state.catalog.length)];
                document.getElementById('proof-img').src = p.img;
                document.getElementById('proof-text').innerText = `${u} just ordered ${p.title}!`;
                document.getElementById('social-proof').classList.add('active');
                setTimeout(() => document.getElementById('social-proof').classList.remove('active'), 5000);
            }
        }, 35000);
    }

})();

document.addEventListener('DOMContentLoaded', App.init);
window.addEventListener('scroll', () => {
    const p = (window.scrollY / (document.documentElement.scrollHeight - window.innerHeight)) * 100;
    document.getElementById("scroll-fill").style.width = p + "%";
});
